请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-007

=== 用户原始指令 (query.txt) ===
整个专注统计卡片呗,要看数据比例,点一下能进系统,能读日历,显示已完成

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个专注统计卡片呗,要看数据比例,点一下能进系统,能读日历,显示已完成",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "今日从日历读取的专注安排或专注时段列表",
          "sampleValue": [
            {
              "entityId": "focus-20260709-001",
              "title": "深度专注",
              "dtStart": "09:00",
              "dtEnd": "10:00"
            }
          ],
          "items": {
            "type": "object",
            "description": "单条日历事件",
            "properties": {
              "entityId": {
                "type": "string",
                "description": "日历事件唯一标识符",
                "sampleValue": "focus-20260709-001"
              },
              "title": {
                "type": "string",
                "description": "日历事件标题",
                "sampleValue": "深度专注"
              },
              "dtStart": {
                "type": "string",
                "description": "日历事件开始时间",
                "sampleValue": "09:00"
              },
              "dtEnd": {
                "type": "string",
                "description": "日历事件结束时间",
                "sampleValue": "10:00"
              }
            }
          }
        }
      }
    },
    "focus": {
      "completionPercent": {
        "type": "integer",
        "description": "专注统计已完成比例，取值 0 到 100",
        "sampleValue": 82
      },
      "completionTotal": {
        "type": "integer",
        "description": "专注统计比例总量",
        "sampleValue": 100
      },
      "completionText": {
        "type": "string",
        "description": "专注统计已完成比例展示文本",
        "sampleValue": "82%"
      },
      "statusText": {
        "type": "string",
        "description": "当前专注统计完成状态",
        "sampleValue": "已完成"
      },
      "durationText": {
        "type": "string",
        "description": "今日已完成专注时长摘要",
        "sampleValue": "2小时"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注模式图标，适合用于专注统计卡片的服务识别。"
    }
  ]
}

